// LinkedIn (reported Mar 2026, LeetCode Discuss) — common ancestor in a parent/child graph.
// An ancestor is a parent, a parent's parent, and so on (never the person themselves).
public static class Ancestry {
    // child -> its parents
    private static Dictionary<int, List<int>> ParentsOf(int[][] pairs) {
        var parents = new Dictionary<int, List<int>>();
        foreach (var p in pairs) {
            if (!parents.TryGetValue(p[1], out var list)) parents[p[1]] = list = new List<int>();
            list.Add(p[0]);
        }
        return parents;
    }

    // Every ancestor of x, walking up with an explicit stack (people can be reached by two routes: use a set).
    private static HashSet<int> AncestorsOf(Dictionary<int, List<int>> parents, int x) {
        var seen = new HashSet<int>();
        var stack = new Stack<int>();
        if (parents.TryGetValue(x, out var first)) foreach (int p in first) stack.Push(p);
        while (stack.Count > 0) {
            int y = stack.Pop();
            if (!seen.Add(y)) continue;
            if (parents.TryGetValue(y, out var up)) foreach (int p in up) stack.Push(p);
        }
        return seen;
    }

    public static bool HasCommonAncestor(int[][] pairs, int a, int b) {
        var parents = ParentsOf(pairs);
        var mine = AncestorsOf(parents, a);
        if (mine.Count == 0) return false;
        foreach (int y in AncestorsOf(parents, b)) if (mine.Contains(y)) return true;
        return false;
    }

    // Follow-up: the earliest known ancestor — the one farthest away. Ties → the smallest id. None → -1.
    public static int EarliestAncestor(int[][] pairs, int x) {
        var parents = ParentsOf(pairs);
        var dist = new Dictionary<int, int> { [x] = 0 };
        var queue = new Queue<int>();
        queue.Enqueue(x);
        int best = -1, bestDist = 0;
        while (queue.Count > 0) {                       // BFS upwards: the first distance found is the shortest
            int y = queue.Dequeue();
            if (!parents.TryGetValue(y, out var up)) continue;
            foreach (int p in up) {
                if (dist.ContainsKey(p)) continue;
                dist[p] = dist[y] + 1;
                queue.Enqueue(p);
                if (dist[p] > bestDist || (dist[p] == bestDist && p < best)) { best = p; bestDist = dist[p]; }
            }
        }
        return best;
    }
}
